const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const api=p=>new URL(p.replace(/^\//,''),document.baseURI).toString();
const baseZones=['North Vineyard','South Vineyard','Cellar','Winery','Estate Gate','Guest House','Unassigned'];
const deviceTypes=['Camera','Environmental sensor','Irrigation controller','Gateway / router','Security device','Vehicle / equipment','Other IoT'];
const securityFields=[['imsi','IMSI','001010000000001'],['k','K · 32 HEX',''],['opc','OPc · 32 HEX',''],['amf','AMF · 4 HEX','8000'],['apn','APN',window.LTE_CONFIG.apn],['msisdn','MSISDN · OPTIONAL','']];
let subscribers=[];
let pendingRegistrations=[];
let pendingApprovalImsi=null;
let activeZone='All zones';
let activeType='All roles';
let deviceSearch='';

function applyTheme(theme,persist=false){
  const dark=theme==='dark';document.documentElement.dataset.theme=dark?'dark':'light';
  $('#theme-toggle').setAttribute('aria-pressed',String(dark));$('#theme-toggle').setAttribute('aria-label',dark?'Use light mode':'Use dark mode');
  $('#theme-icon').setAttribute('href',dark?'#i-sun':'#i-moon');$('#theme-label').textContent=dark?'Light':'Dark';
  document.querySelector('meta[name="theme-color"]').content=dark?'#11100e':'#f2eee4';
  if(persist)try{localStorage.setItem('baiamonte-lte-theme',dark?'dark':'light')}catch(e){}
}
applyTheme(document.documentElement.dataset.theme);
$('#theme-toggle').onclick=()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true);

function secureFieldsMarkup(compact=false){return securityFields.filter(([name])=>!compact||name!=='msisdn').map(([name,label,placeholder])=>`<div class="field"><label>${label}</label><input name="${name}" placeholder="${placeholder}" value="${['amf','apn'].includes(name)?placeholder:''}" ${['k','opc'].includes(name)?'type="password" autocomplete="off"':''}></div>`).join('')}
function fieldMarkup(compact=false){
  if(compact)return `<div class="field"><label>DEVICE NAME</label><input name="name" placeholder="North gate camera"></div>${secureFieldsMarkup(true)}`;
  return `<div class="field"><label>DEVICE NAME</label><input name="name" placeholder="North gate camera"></div>
    <div class="field"><label>DEVICE ROLE</label><select name="device_type">${deviceTypes.map(type=>`<option ${type==='Other IoT'?'selected':''}>${type}</option>`).join('')}</select></div>
    <div class="field"><label>VINEYARD ZONE</label><input name="zone" placeholder="North Vineyard" list="estate-zones"></div>
    <label class="field critical-field"><span>CRITICAL ASSET</span><input type="checkbox" name="critical"><i></i><small>Highlight this device for daily operations</small></label>
    <div class="field wide"><label>OPERATIONS NOTES</label><textarea name="notes" maxlength="160" placeholder="Location, purpose, expected reporting interval, or recorder"></textarea></div>
    ${secureFieldsMarkup()}`;
}
function simSecretField(name,label,type='password'){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" autocomplete="off"></div>`}
function simFieldMarkup(){return `<div class="field"><label>DEVICE NAME</label><input name="name" placeholder="North gate camera"></div><div class="field"><label>DEVICE ROLE</label><select name="device_type">${deviceTypes.map(type=>`<option ${type==='Camera'?'selected':''}>${type}</option>`).join('')}</select></div><div class="field"><label>VINEYARD ZONE</label><input name="zone" placeholder="Estate Gate" list="estate-zones"></div><div class="field"><label>ICCID · CARD / INVENTORY</label><input name="iccid" inputmode="numeric" placeholder="Read or generated candidate"></div><div class="field"><label>IMSI</label><input name="imsi" inputmode="numeric" placeholder="Generated under configured PLMN"></div><div class="field"><label>APN</label><input name="apn" value="${escapeHtml(window.LTE_CONFIG.apn)}"></div><details class="sim-secret-fields" open><summary>Authentication &amp; card values</summary><div>${simSecretField('k','K · 32 HEX')}${simSecretField('op','OP · 32 HEX')}${simSecretField('opc','OPc · 32 HEX')}${simSecretField('amf','AMF · 4 HEX','text')}${simSecretField('pin1','PIN1 · PRIVATE','text')}${simSecretField('puk1','PUK1 · PRIVATE','text')}</div></details>`}
$('#ue-form').innerHTML=fieldMarkup();
$('#sim-form').innerHTML=simFieldMarkup();

function badge(el,online){el.textContent=online?'Online':'Offline';el.className=`badge ${online?'online':'offline'}`}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
function escapeHtml(s){const d=document.createElement('div');d.textContent=s??'';return d.innerHTML}
async function jsonFetch(path,opt){const r=await fetch(api(path),opt);const j=await r.json();if(!r.ok)throw new Error(j.error||'Request failed');return j}
function formatDuration(seconds){seconds=Math.max(0,Number(seconds||0));if(seconds<60)return `${seconds}s`;if(seconds<3600)return `${Math.round(seconds/60)}m`;if(seconds<86400)return `${Math.round(seconds/3600)}h`;return `${Math.round(seconds/86400)}d`}
function formatAge(timestamp){if(!timestamp)return 'No sample yet';const seconds=Math.max(0,Math.round(Date.now()/1000-timestamp));return seconds<10?'just now':`${formatDuration(seconds)} ago`}
function renderSubscriberGauges(data){
  const measured=data.items.filter(item=>item.value!==null),timestamps=data.items.map(item=>item.updated_at).filter(Boolean),oldest=timestamps.length?Math.min(...timestamps):null;
  $('#subscriber-gauge-freshness').textContent=measured.length===data.items.length?`Updated ${formatAge(oldest)}`:`${measured.length} of ${data.items.length} measured`;
  $('#subscriber-gauge-freshness').className=`badge ${measured.length===data.items.length?'online':'neutral'}`;
  $('#subscriber-gauges').innerHTML=data.items.map(item=>{const value=item.value===null?0:Math.max(0,Math.min(100,item.value)),state=item.value===null?'unknown':value>=85?'good':value>=50?'warning':'bad';return `<div class="subscriber-gauge ${state}"><div class="gauge-dial" style="--gauge-value:${value}" role="img" aria-label="${escapeHtml(item.label)}: ${escapeHtml(item.display)}"><div><strong>${escapeHtml(item.display)}</strong><small>${item.value===null?'NOT MEASURED':'CURRENT'}</small></div></div><span><b>${escapeHtml(item.label)}</b><small>${escapeHtml(item.detail)}</small><em>${escapeHtml(item.source)}${item.updated_at?` · ${formatAge(item.updated_at)}`:''}</em></span></div>`}).join('');
}
function renderVisibility(data){
  const score=data.health_score;
  $('#network-health-score').textContent=score===null?'—':`${score}%`;
  $('#network-health-summary').textContent=score===null?'Waiting for measurable signals':score>=90?'Private data network is healthy':score>=65?'Network needs attention':'Immediate network attention required';
  $('#monitor-freshness').textContent=`Monitor sampled ${formatAge(data.monitor_sampled_at)} · ${data.home_assistant_ready?'Home Assistant alerts ready':'Home Assistant alerts unavailable'}`;
  $('#visibility-lights').innerHTML=data.lights.map(item=>`<div class="visibility-light ${item.state}" title="${escapeHtml(item.detail)}"><i></i><span><small>${escapeHtml(item.label)}</small><b>${item.state==='online'?'Ready':item.state==='offline'?'Attention':'Not verified'}</b><em>${escapeHtml(item.detail)}${item.latency_ms!==null&&item.latency_ms!==undefined?` · ${item.latency_ms} ms`:''}</em></span></div>`).join('');
  $('#next-actions').innerHTML=data.actions.length?data.actions.map((action,index)=>`<div class="next-action"><b>${index+1}</b><span><strong>${escapeHtml(action.title)}</strong><small>${escapeHtml(action.detail)}</small></span></div>`).join(''):'<div class="all-clear"><b>All measured paths are ready</b><span>Unknown items still require their own verification.</span></div>';
  $('#incident-timeline').innerHTML=data.incidents.length?data.incidents.slice(0,6).map(item=>`<div class="incident ${item.state}"><i></i><span><b>${escapeHtml(item.label)} ${item.state}</b><small>${new Date(item.started_at*1000).toLocaleString()}${item.duration_seconds?` · ${formatDuration(item.duration_seconds)}`:''}</small></span></div>`).join(''):'<div class="empty">No state changes recorded in the last seven days.</div>';
  const counters=data.routing?.counters;
  $('#traffic-evidence').innerHTML=`<div><small>NAT PACKETS</small><b>${counters?.nat?.toLocaleString?.()??'—'}</b></div><div><small>OUTBOUND</small><b>${counters?.outbound?.toLocaleString?.()??'—'}</b></div><div><small>RETURN</small><b>${counters?.return?.toLocaleString?.()??'—'}</b></div><p>${data.ue_verification?.verified?'A live subscriber traffic test has passed.':counters?'Counters are from the last routing check; run a live UE test for end-to-end proof.':'Run Check current routing to collect EPC counters.'}</p>`;
}

async function refresh(){
  const button=$('#refresh');button.classList.add('loading');button.disabled=true;
  try{
    const d=await jsonFetch('api/overview');
    badge($('#epc-badge'),d.epc.online);badge($('#bts-badge'),d.bts.online);
    renderVisibility(d.visibility);
    renderSubscriberGauges(d.subscriber_gauges);
    $('#s1-status').textContent=d.epc.s1.online?`${d.epc.s1.latency_ms} ms`:'Closed';
    $('#db-status').textContent=d.epc.database.online?'Reachable':'Unavailable';
    $('#ue-count').textContent=d.subscriber_count;
    $('#camera-count').textContent=d.inventory?.cameras??0;
    $('#iot-count').textContent=d.inventory?.iot??0;
    $('#critical-count').textContent=d.inventory?.critical??0;
    const healthy=d.epc.online&&d.bts.online,partial=d.epc.online||d.bts.online;
    $('#estate-status').textContent=healthy?'Ready':partial?'Needs attention':'Action needed';
    $('#estate-status').className=healthy?'good':partial?'warn':'bad';
    $('#estate-health').textContent=healthy?'Estate network ready for operations':partial?'Part of the estate network needs attention':'Core and radio are currently unreachable';
    $('#hero-pulse').classList.toggle('alert',!healthy);
    $('#last-checked').textContent=`Checked ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;
    $('#events').innerHTML=d.events.length?d.events.map(e=>`<div class="event">${escapeHtml(e.message)}<small>${new Date(e.created_at*1000).toLocaleString()}</small></div>`).join(''):'<div class="empty">No events yet</div>';
    await Promise.all([loadUEs(),loadPendingRegistrations(),loadHistory(currentHistoryHours()),loadAlertSettings()]);
  }catch(e){
    $('#estate-status').textContent='Check failed';$('#estate-status').className='bad';
    $('#estate-health').textContent='Unable to read the estate network';toast(e.message);
  }finally{button.classList.remove('loading');button.disabled=false}
}

function zoneOptions(current){return [...new Set([current,...baseZones,...subscribers.map(row=>row.zone)])].filter(Boolean).map(zone=>`<option ${zone===current?'selected':''}>${escapeHtml(zone)}</option>`).join('')}
function roleOptions(current){return deviceTypes.map(type=>`<option ${type===current?'selected':''}>${type}</option>`).join('')}
function renderSubscribers(){
  const query=deviceSearch.trim().toLowerCase();
  const visible=subscribers.filter(row=>(activeZone==='All zones'||row.zone===activeZone)&&(activeType==='All roles'||row.device_type===activeType)&&(!query||[row.name,row.imsi,row.zone,row.device_type,row.notes].some(value=>String(value||'').toLowerCase().includes(query))));
  const counts=subscribers.reduce((map,row)=>(map[row.zone]=(map[row.zone]||0)+1,map),{});
  $('#zone-summary').innerHTML=[['All zones',subscribers.length],...Object.entries(counts).sort()].map(([zone,count])=>`<button class="zone-chip ${zone===activeZone?'active':''}" data-zone-filter="${escapeHtml(zone)}"><svg><use href="#i-zone"></use></svg><span>${escapeHtml(zone)}</span><b>${count}</b></button>`).join('');
  $('#ue-rows').innerHTML=visible.map(row=>`<tr><td><b>${escapeHtml(row.name)}</b>${row.notes?`<small class="device-note">${escapeHtml(row.notes)}</small>`:''}</td><td><select class="role-select" data-profile-imsi="${row.imsi}">${roleOptions(row.device_type)}</select></td><td><select class="zone-select" data-zone-imsi="${row.imsi}">${zoneOptions(row.zone)}</select></td><td><label class="critical-toggle" title="Mark as operationally critical"><input type="checkbox" data-critical-imsi="${row.imsi}" ${row.critical?'checked':''}><i></i><span>${row.critical?'Critical':'Standard'}</span></label></td><td>${row.imsi}</td><td>${escapeHtml(row.apn)}</td><td><button data-delete="${row.imsi}" title="Remove">Remove</button></td></tr>`).join('');
  $('#ue-empty').style.display=visible.length?'none':'block';
  $('#ue-empty').textContent=subscribers.length?'No devices match these filters.':'No estate devices provisioned yet.';
  $$('[data-zone-filter]').forEach(button=>button.onclick=()=>{activeZone=button.dataset.zoneFilter;renderSubscribers()});
  $$('[data-zone-imsi]').forEach(select=>select.onchange=async()=>{try{await jsonFetch(`api/subscribers/${select.dataset.zoneImsi}/zone`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({zone:select.value})});toast('Vineyard zone updated');await loadUEs()}catch(e){toast(e.message)}});
  $$('[data-profile-imsi]').forEach(select=>select.onchange=async()=>{try{await updateProfile(select.dataset.profileImsi,{device_type:select.value});toast('Device role updated');await loadUEs()}catch(e){toast(e.message)}});
  $$('[data-critical-imsi]').forEach(input=>input.onchange=async()=>{try{await updateProfile(input.dataset.criticalImsi,{critical:input.checked});toast(input.checked?'Critical device highlighted':'Critical flag removed');await loadUEs()}catch(e){toast(e.message)}});
  $$('[data-delete]').forEach(button=>button.onclick=async()=>{if(!confirm(`Remove UE ${button.dataset.delete} from the EPC?`))return;try{await jsonFetch(`api/subscribers/${button.dataset.delete}`,{method:'DELETE'});toast('UE removed');refresh()}catch(e){toast(e.message)}});
}
function updateProfile(imsi,body){return jsonFetch(`api/subscribers/${imsi}/profile`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}
async function loadUEs(){subscribers=await jsonFetch('api/subscribers');renderSubscribers()}

function renderPendingRegistrations(){
  $('#pending-count').textContent=pendingRegistrations.length?`${pendingRegistrations.length} awaiting review`:'Queue clear';
  $('#pending-count').className=`badge ${pendingRegistrations.length?'offline':'online'}`;
  $('#pending-registrations').innerHTML=pendingRegistrations.length?pendingRegistrations.map(row=>`<div class="pending-registration"><i></i><div><small>UNKNOWN SUBSCRIBER</small><b>${escapeHtml(row.imsi)}</b><span>${escapeHtml(row.cause)}${row.apn?` · requested APN ${escapeHtml(row.apn)}`:''}</span><em>${row.attempts} observed scan${row.attempts===1?'':'s'} · last seen ${formatAge(row.last_seen)} · ${escapeHtml(row.source)}</em></div><div class="pending-actions"><button class="primary small" data-approve-registration="${row.imsi}">Review &amp; approve</button><button class="secondary small" data-dismiss-registration="${row.imsi}">Dismiss</button></div></div>`).join(''):'<div class="all-clear"><b>No unknown subscribers await approval</b><span>Scan recent EPC logs or upload an MME log after a rejected device attempts to attach.</span></div>';
  $$('[data-approve-registration]').forEach(button=>button.onclick=()=>openPendingApproval(button.dataset.approveRegistration));
  $$('[data-dismiss-registration]').forEach(button=>button.onclick=async()=>{const imsi=button.dataset.dismissRegistration;if(!confirm(`Dismiss the registration request from IMSI ${imsi}?`))return;try{await jsonFetch(`api/registrations/pending/${imsi}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:imsi})});toast('Pending registration dismissed');loadPendingRegistrations()}catch(e){toast(e.message)}});
}
async function loadPendingRegistrations(){pendingRegistrations=await jsonFetch('api/registrations/pending');renderPendingRegistrations();renderTroubleshootingPending()}
function resetUeDialog(){pendingApprovalImsi=null;$('#ue-dialog-eyebrow').textContent='TRUSTED DEVICE PROFILE';$('#ue-dialog-title').textContent='Add estate device';$('#save-ue').textContent='Provision device';$('#approval-context').hidden=true;$('#approval-context').textContent='';$('#ue-dialog form').reset();$('#ue-form [name="amf"]').value='8000';$('#ue-form [name="apn"]').value=window.LTE_CONFIG.apn;$('#ue-form [name="imsi"]').readOnly=false;$('#form-error').textContent=''}
function openPendingApproval(imsi){const row=pendingRegistrations.find(item=>item.imsi===imsi);if(!row)return;resetUeDialog();pendingApprovalImsi=imsi;$('#ue-dialog-eyebrow').textContent='ADMIN SUBSCRIBER APPROVAL';$('#ue-dialog-title').textContent='Approve registration';$('#save-ue').textContent='Approve & provision';$('#ue-form [name="imsi"]').value=imsi;$('#ue-form [name="imsi"]').readOnly=true;$('#ue-form [name="apn"]').value=row.apn||window.LTE_CONFIG.apn;$('#ue-form [name="name"]').value=`Pending device ${imsi.slice(-6)}`;$('#approval-context').hidden=false;$('#approval-context').innerHTML=`<b>Observed registration information</b><span>IMSI ${escapeHtml(imsi)}${row.apn?` · APN ${escapeHtml(row.apn)}`:''} · ${escapeHtml(row.cause)}</span><small>K and OPc must come from the matching physical SIM record; they cannot be recovered from the attach request.</small>`;$('#ue-dialog').showModal()}
function renderTroubleshootingPending(){const target=$('#troubleshooting-pending');if(!target)return;target.innerHTML=pendingRegistrations.length?`<div class="pending-troubleshooting-head"><b>${pendingRegistrations.length} registration${pendingRegistrations.length===1?'':'s'} ready for review</b><button class="primary small" id="open-pending-from-troubleshooting">Open approval queue</button></div>`+pendingRegistrations.slice(0,3).map(row=>`<div class="tool-result-row"><span><b>IMSI ${escapeHtml(row.imsi)}</b><small>${escapeHtml(row.cause)} · ${formatAge(row.last_seen)}</small></span><button class="secondary small" data-troubleshooting-approve="${row.imsi}">Approve</button></div>`).join(''):'<div class="empty">No provisionable unknown subscribers found in analyzed logs.</div>';$('#open-pending-from-troubleshooting')?.addEventListener('click',()=>showPage('ues'));$$('[data-troubleshooting-approve]').forEach(button=>button.onclick=()=>openPendingApproval(button.dataset.troubleshootingApprove))}

$('#device-search').oninput=event=>{deviceSearch=event.target.value;renderSubscribers()};
$('#device-type-filter').onchange=event=>{activeType=event.target.value;renderSubscribers()};

function currentHistoryHours(){return Number($('.range-picker .active')?.dataset.hours||24)}
function historyPath(points,key,onlineY,offlineY,width){
  if(!points.length)return '';
  const first=points[0].sampled_at,last=points[points.length-1].sampled_at,span=Math.max(last-first,1);
  let path='';
  points.forEach((point,index)=>{const x=16+(point.sampled_at-first)/span*(width-32),y=point[key]?onlineY:offlineY;if(index===0)path=`M ${x} ${y}`;else path+=` H ${x} V ${y}`});
  return path;
}
async function loadHistory(hours=24){
  try{
    const data=await jsonFetch(`api/history?hours=${hours}`),width=720;
    $('#epc-uptime').textContent=data.uptime.epc===null?'No data':`${data.uptime.epc}%`;
    $('#radio-uptime').textContent=data.uptime.radio===null?'No data':`${data.uptime.radio}%`;
    $('#history-samples').textContent=data.points.length?`${data.points.length} checks recorded`:'History begins after the first check';
    if(!data.points.length){$('#history-chart').innerHTML='<div class="empty chart-empty">Monitoring is starting. Availability will appear here automatically.</div>';return}
    const epc=historyPath(data.points,'epc_online',38,62,width),radio=historyPath(data.points,'bts_online',98,122,width);
    $('#history-chart').innerHTML=`<svg viewBox="0 0 ${width} 150" role="img" aria-label="Connection history"><line x1="16" y1="75" x2="704" y2="75" class="chart-divider"/><text x="16" y="20">EPC</text><text x="16" y="88">RADIO</text><path d="${epc}" class="chart-line epc-line"/><path d="${radio}" class="chart-line radio-line"/><text x="16" y="146">${hours===168?'7 days ago':hours+' hours ago'}</text><text x="704" y="146" text-anchor="end">Now</text></svg>`;
  }catch(e){$('#history-chart').innerHTML='<div class="empty chart-empty">History is temporarily unavailable.</div>'}
}
$$('.range-picker button').forEach(button=>button.onclick=()=>{$$('.range-picker button').forEach(b=>b.classList.toggle('active',b===button));loadHistory(Number(button.dataset.hours))});

async function loadAlertSettings(){
  try{
    const data=await jsonFetch('api/alerts/settings'),form=$('#alert-form'),prefs=data.settings;
    form.elements.epc_enabled.checked=prefs.epc_enabled;form.elements.radio_enabled.checked=prefs.radio_enabled;
    form.elements.failure_threshold.value=String(prefs.failure_threshold);form.elements.cooldown_minutes.value=String(prefs.cooldown_minutes);
    const active=Object.entries(data.states).filter(([,state])=>state.active).map(([name])=>name.toUpperCase());
    $('#alert-readiness').className=`alert-readiness ${data.home_assistant_ready?'ready':'warning'}`;
    $('#alert-readiness').textContent=active.length?`Active alert: ${active.join(' + ')}`:data.home_assistant_ready?'Home Assistant notifications ready':'Notifications become active when installed in Home Assistant';
  }catch(e){$('#alert-readiness').textContent='Alert settings unavailable'}
}
$('#alert-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,body={epc_enabled:form.elements.epc_enabled.checked,radio_enabled:form.elements.radio_enabled.checked,failure_threshold:Number(form.elements.failure_threshold.value),cooldown_minutes:Number(form.elements.cooldown_minutes.value)};try{await jsonFetch('api/alerts/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast('Alert rules saved');loadAlertSettings()}catch(e){toast(e.message)}};

$$('.nav').forEach(button=>button.onclick=()=>showPage(button.dataset.page));$$('[data-go]').forEach(button=>button.onclick=()=>showPage(button.dataset.go));
function showPage(id,updateHash=true){if(!document.getElementById(id))id='overview';$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===id));$$('.page').forEach(p=>p.classList.toggle('active',p.id===id));$('#page-title').textContent={overview:'Vineyard network',ues:'Estate devices',bts:'Estate radio',sim:'SIM workbench',diagnostics:'Network care'}[id];if(updateHash&&location.hash!==`#${id}`)history.replaceState(null,'',`#${id}`);if(id==='bts'){loadBtsStatus();loadNokiaOperations();loadNokiaControls();loadNetworkProfile()}if(id==='sim')readerStatus();if(id==='diagnostics'){loadLogs();loadInternetPlan();loadRoutingAssistant();loadCommunications()}window.scrollTo({top:0,behavior:'smooth'})}
$('#refresh').onclick=refresh;$('#add-ue').onclick=()=>{resetUeDialog();$('#ue-dialog').showModal()};
$$('[data-action]').forEach(button=>button.onclick=()=>{const action=button.dataset.action;if(action==='add-ue'){showPage('ues');$('#add-ue').click()}else if(action==='diagnostics'){showPage('diagnostics');$('#run-diagnostics').click()}else showPage(action)});
$('#save-ue').onclick=async()=>{const body=Object.fromEntries(new FormData($('#ue-dialog form'))),pending=pendingApprovalImsi;try{if(pending){body.confirm=pending;await jsonFetch(`api/registrations/pending/${pending}/approve`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}else await jsonFetch('api/subscribers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#ue-dialog').close();resetUeDialog();toast(pending?'Subscriber approved and provisioned':'Estate device provisioned');refresh()}catch(e){$('#form-error').textContent=e.message}};
function btsPollCard(label,state,detail,meta=''){return `<div class="bts-poll-card ${state}"><i></i><span><small>${escapeHtml(label)}</small><b>${state==='online'?'Ready':state==='offline'?'Unavailable':'Not measured'}</b><em>${escapeHtml(detail)}</em>${meta?`<code>${escapeHtml(meta)}</code>`:''}</span></div>`}
let lastBtsStatus=null;
async function loadBtsStatus(){
  const button=$('#poll-bts');button.disabled=true;button.textContent='Polling…';
  try{
    const data=await jsonFetch('api/bts/status'),https=data.management.https,http=data.management.http,management=https.online||http.online,apiState=data.management.api||{},commission=data.commissioning,fields=Object.values(commission.fields||{}),access=commission.access;lastBtsStatus=data;
    $('#bts-poll-state').className=`badge ${data.reachable?'online':'offline'}`;
    $('#bts-poll-state').textContent=data.reachable?`Polled ${new Date(data.sampled_at*1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`:'Radio unreachable';
    const fingerprint=https.certificate_sha256?`SHA256 ${https.certificate_sha256.match(/.{1,2}/g).join(':')}`:'';
    $('#bts-poll-grid').innerHTML=
      btsPollCard('Radio IP',data.reachable?'online':'offline',`${data.host} ${data.ping.online?'answers ICMP':'did not answer ICMP'}`)+
      btsPollCard('Management plane',management?'online':'offline',https.online?`HTTPS ${https.protocol||''} · ${https.latency_ms} ms`:http.online?`HTTP reachable · ${http.latency_ms} ms`:'HTTP and HTTPS unavailable',fingerprint)+
      btsPollCard('EPC S1 listener',data.s1_target.online?'online':'offline',`${data.s1_target.host}:${data.s1_target.port}${data.s1_target.latency_ms!==null?` · ${data.s1_target.latency_ms} ms`:''}`)+
      btsPollCard('Nokia data feed',!apiState.enabled?'unknown':apiState.authenticated?'online':'offline',!apiState.enabled?'Enable the optional management gateway':apiState.detail||'No endpoint response',apiState.status?`HTTP ${apiState.status}${apiState.latency_ms!==null?` · ${apiState.latency_ms} ms`:''}`:'')+
      btsPollCard('Commissioning context',!commission.available?'unknown':commission.valid?'online':'offline',!commission.available?'Import the Nokia backup for configuration context':commission.valid?`${fields.length} safe fields read from ${commission.file}`:'Stored file could not be parsed')+
      (access?`<div class="bts-access-result"><small>ACCESS DISCOVERED</small><b>${escapeHtml(access.method)}</b><span>${escapeHtml(access.detail)}</span><div><em class="pass">HTTPS${access.tls_required?' required':''}</em><em class="${access.ssh_enabled?'pass':'fail'}">SSH ${access.ssh_enabled?'enabled':'disabled'}</em><em class="neutral">SNMP not configured</em></div></div>`:'')+
      (fields.length?`<div class="bts-config-context">${fields.map(field=>`<div><small>${escapeHtml(field.label)}</small><b>${escapeHtml(field.value)}</b></div>`).join('')}</div>`:'');
    $('#bts-license-note').textContent=data.licensed_status.detail;
  }catch(e){$('#bts-poll-state').className='badge offline';$('#bts-poll-state').textContent='Poll failed';$('#bts-poll-grid').innerHTML=`<div class="connection-result error">${escapeHtml(e.message)}</div>`}
  finally{button.disabled=false;button.textContent='Poll Nokia'}
}
$('#poll-bts').onclick=loadBtsStatus;
function nokiaMessageClass(severity){const value=String(severity||'').toLowerCase();if(/critical|major|fatal|error/.test(value))return 'critical';if(/minor|warning|warn/.test(value))return 'warning';if(/clear|cleared|normal|ok/.test(value))return 'cleared';return 'info'}
async function loadNokiaOperations(){
  const button=$('#refresh-nokia-operations');button.disabled=true;button.textContent='Refreshing…';
  try{
    const data=await jsonFetch('api/nokia/operations'),state=$('#nokia-operations-state'),endpoints=Object.entries(data.endpoints||{});
    const connected=data.summary.reachable_endpoints>0;
    state.className=`badge ${connected?'online':data.enabled?'offline':'neutral'}`;
    state.textContent=connected?`Live · ${new Date(data.sampled_at*1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`:data.enabled?'Gateway unavailable':'Gateway disabled';
    $('#nokia-endpoint-state').innerHTML=endpoints.map(([name,item])=>`<span class="${item.reachable?'pass':item.configured?'fail':'neutral'}"><i></i>${escapeHtml(name)} · ${item.reachable?'online':item.configured?'unavailable':'not configured'}</span>`).join('');
    $('#nokia-status-grid').innerHTML=data.statuses.length?data.statuses.map(item=>profileItem(item.label,item.value)).join(''):`<div class="empty">${data.enabled?'No recognized operational fields were returned. Check the configured endpoint paths and gateway response format.':'Enable nokia_api_enabled and configure the HTTPS endpoint paths in Home Assistant.'}</div>`;
    $('#nokia-message-count').textContent=`${data.messages.length} message${data.messages.length===1?'':'s'}`;
    $('#nokia-message-list').innerHTML=data.messages.length?data.messages.map(item=>`<div class="nokia-message ${nokiaMessageClass(item.severity)}"><i></i><span><b>${escapeHtml(item.message)}</b><small>${escapeHtml(item.source)}${item.timestamp?` · ${escapeHtml(item.timestamp)}`:''}</small></span><em>${escapeHtml(item.severity)} · ${escapeHtml(item.kind)}</em></div>`).join(''):'<div class="empty">No active alarms or operational events were returned.</div>';
  }catch(e){$('#nokia-operations-state').className='badge offline';$('#nokia-operations-state').textContent='Feed failed';$('#nokia-status-grid').innerHTML=`<div class="connection-result error">${escapeHtml(e.message)}</div>`}
  finally{button.disabled=false;button.textContent='Refresh feed'}
}
$('#refresh-nokia-operations').onclick=loadNokiaOperations;
async function loadNokiaControls(){try{const data=await jsonFetch('api/nokia/control'),state=$('#nokia-control-state');state.className=`badge ${data.ready?'online':'neutral'}`;state.textContent=data.ready?'Controls ready':'Disabled';$('#nokia-control-actions').innerHTML=data.actions.map(item=>`<button class="nokia-control-button ${item.id==='restart_cell'||item.id==='cell_lock'?'caution':''}" data-nokia-action="${escapeHtml(item.id)}" data-nokia-label="${escapeHtml(item.label)}" ${data.ready?'':'disabled'}><b>${escapeHtml(item.label)}</b><small>${escapeHtml(item.detail)}</small></button>`).join('');if(!data.ready)$('#nokia-control-result').innerHTML=`<div class="empty">${escapeHtml(data.detail)}</div>`;$$('[data-nokia-action]').forEach(button=>button.onclick=()=>runNokiaControl(button))}catch(e){$('#nokia-control-state').className='badge offline';$('#nokia-control-state').textContent='Unavailable'}}
async function runNokiaControl(button){const action=button.dataset.nokiaAction,label=button.dataset.nokiaLabel,confirmation=prompt(`${label} can affect radio service. Type ${action.toUpperCase()} to continue.`);if(confirmation===null)return;button.disabled=true;try{const data=await routingPost('api/nokia/control',{action,confirm:confirmation});$('#nokia-control-result').innerHTML=`<div class="connection-result success"><b>${escapeHtml(data.label)} accepted by the configured gateway</b><span>Refresh the operations feed to confirm the resulting Nokia state.</span></div>`;toast(`${data.label} requested`);setTimeout(()=>{loadBtsStatus();loadNokiaOperations()},1500)}catch(e){$('#nokia-control-result').innerHTML=`<div class="connection-result error">${escapeHtml(e.message)}</div>`;toast(e.message)}finally{button.disabled=false}}
function profileItem(label,value){return `<div><small>${escapeHtml(label)}</small><b>${escapeHtml(String(value))}</b></div>`}
async function loadNetworkProfile(){try{const data=await jsonFetch('api/network-profile'),r=data.radio,s=data.subscriber,c=data.channel,state=$('#network-profile-state');state.className=`badge ${data.valid?'online':'offline'}`;state.textContent=data.valid?'Profile valid':'Review profile';$('#network-profile-grid').innerHTML=[profileItem('Network / PLMN',`${r.network_name} · ${data.plmn}`),profileItem('MME identity',`Group ${r.mme_group_id} · code ${r.mme_code}`),profileItem('Tracking / cell',`TAC ${r.tac} · eNB ${r.enb_id} · cell ${r.cell_id}`),profileItem('Radio channel',`Band ${r.lte_band} · DL ${r.dl_earfcn} · UL ${r.ul_earfcn}`),profileItem('PCI / bandwidth',`PCI ${r.pci} · ${r.channel_bandwidth_mhz} MHz`),profileItem('RF target',`${r.tx_power_dbm} dBm`),profileItem('Core ports',`S1AP ${r.s1ap_port} · GTP-U ${r.gtpu_port}`),profileItem('APN / address pool',`${s.apn} · ${s.ue_subnet}`),profileItem('Gateway / IP mode',`${s.ue_gateway} · ${s.subscriber_ip_version}`),profileItem('DNS / MTU',`${s.subscriber_dns_primary}, ${s.subscriber_dns_secondary} · ${s.subscriber_mtu}`),profileItem('QoS / AMBR',`QCI ${s.default_qci} · ${s.ambr_downlink_mbps}/${s.ambr_uplink_mbps} Mbps`),profileItem('USIM selection',`${s.home_plmn_only?'Home only':'Policy based'} · ${s.preferred_plmns}`)].join('');$('#network-profile-checks').innerHTML=data.checks.map(check=>`<span class="${check.ok?'pass':'fail'}" title="${escapeHtml(check.detail)}">${check.ok?'✓':'!'} ${escapeHtml(check.label)}</span>`).join('');$('#radio-channel-state').className=`badge ${c.supported?'online':'neutral'}`;$('#radio-channel-state').textContent=`Band ${c.band} · ${c.duplex}`;$('#radio-channel-grid').innerHTML=[profileItem('eNodeB TX / downlink',c.supported?`${c.enb_tx_mhz} MHz · EARFCN ${c.dl_earfcn}`:`EARFCN ${c.dl_earfcn}`),profileItem('eNodeB RX / uplink',c.supported?`${c.enb_rx_mhz} MHz · EARFCN ${c.ul_earfcn}`:`EARFCN ${c.ul_earfcn}`),profileItem('Occupied channel',`${c.bandwidth_mhz} MHz`),profileItem('Duplex spacing',c.supported?`${c.duplex_spacing_mhz} MHz`:'See Nokia readback'),profileItem('Configured TX power',`${c.tx_power_dbm} dBm`),profileItem('Physical cell ID',`PCI ${c.pci??r.pci}`),profileItem('Cell identity',`eNB ${c.enb_id??r.enb_id} · cell ${c.cell_id??r.cell_id}`),profileItem('Live RX / RF evidence','Nokia operations feed')].join('');$('#radio-channel-note').textContent=c.note}catch(e){$('#network-profile-state').className='badge offline';$('#network-profile-state').textContent='Invalid';$('#network-profile-grid').innerHTML=`<div class="connection-result error">${escapeHtml(e.message)}</div>`}}
