async function loadSimProductionPlan(){try{const data=await jsonFetch('api/sim/production-plan'),n=data.network;$('#sim-plmn').className=`badge ${data.profile_valid?'online':'offline'}`;$('#sim-plmn').textContent=`PLMN ${n.plmn}`;$('#sim-production-steps').innerHTML=data.steps.map((step,index)=>`<div class="sim-production-step"><b>${index+1}</b><span><strong>${escapeHtml(step.label)}</strong><small>${escapeHtml(step.detail)}</small></span></div>`).join('');$('#sim-lte-files').innerHTML=data.lte_files.map(item=>`<div><span><b>${escapeHtml(item.file)}</b><small>${escapeHtml(item.purpose)}</small></span><em>${item.required?'Required':'Policy dependent'}</em></div>`).join('');$('#sim-selection-note').innerHTML=`<b>Configured subscriber path</b><br>${escapeHtml(data.selection_note)}<br><br>PLMN ${escapeHtml(n.plmn)} · MNC length ${n.mnc_length} · TAC ${n.tac} · access class ${n.access_class} · APN ${escapeHtml(n.apn)} · ${escapeHtml(n.ip_version)} · MTU ${n.mtu} · QCI ${n.qci} · AMBR ${n.ambr_downlink_mbps}/${n.ambr_uplink_mbps} Mbps DL/UL.<br><br>${escapeHtml(data.write_note)}`}catch(e){toast(e.message)}}
function setIoLight(selector,state,detail){const light=$(selector);light.className=`sim-io-light ${state}`;light.querySelector('small').textContent=detail}
function setSimProcess(stage,label){const stages=['discover','profile','card','worksheet','hss','verify'],index=stages.indexOf(stage);$$('#sim-card-process > div').forEach((item,itemIndex)=>{item.classList.toggle('complete',itemIndex<index);item.classList.toggle('active',itemIndex===index)});$('#sim-process-state').className=`badge ${stage==='verify'?'online':'neutral'}`;$('#sim-process-state').textContent=label||stage}
async function readerStatus(){try{const data=await jsonFetch('api/sim/readers');badge($('#sim-ready'),data.ready);$('#sim-ready').textContent=data.write_ready?'Reader / writer ready':data.read_ready?'Reader ready':'Setup needed';setIoLight('#sim-read-light',data.read_ready?'online':data.readers.length?'warning':'offline',data.read_ready?'Ready':data.readers.length?'Enable access':'Not detected');setIoLight('#sim-write-light',data.write_ready?'online':data.read_ready?'warning':'offline',data.write_ready?'Ready':data.read_ready?'Writer tool needed':'Not detected');const rows=[['USB bus visible',data.usb_visible],['PC/SC reader discovered',data.readers.length>0],['Read access enabled',data.read_ready],['pySim writer discovered',data.pysim_writer],['Physical write ready',data.write_ready]];$('#reader-details').innerHTML=rows.map(([name,ready])=>`<div class="ready-row"><span>${name}</span><b style="color:${ready?'var(--green)':'var(--amber)'}">${ready?'Yes':'No'}</b></div>`).join('')+(data.selected_reader?`<div class="reader-selection"><small>SELECTED · ${escapeHtml(data.protocol)}</small><b>${escapeHtml(data.selected_reader)}</b></div>`:'<div class="warning">No reader selected. Check USB access and the Home Assistant reader name/index configuration.</div>');setSimProcess(data.read_ready?'profile':'discover',data.write_ready?'Reader / writer ready':data.read_ready?'Reader ready':'Discovery needed');loadSimProductionPlan();loadSimInventory()}catch(e){setIoLight('#sim-read-light','offline','Unavailable');setIoLight('#sim-write-light','offline','Unavailable');toast(e.message)}}
function simFormBody(){const body=Object.fromEntries(new FormData($('#sim-form')));body.critical=['Camera','Security device','Irrigation controller'].includes(body.device_type);body.notes=`Production SIM${body.iccid?` · ICCID ${body.iccid}`:''}`;body.commissioning_source='sim_workbench';return body}
function fillSimProfile(data,source='Generated'){const form=$('#sim-form');const aliases={Device:'name',Role:'device_type',Zone:'zone',ICCID:'iccid',IMSI:'imsi',K:'k',OP:'op',OPc:'opc',AMF:'amf',PIN1:'pin1',PUK1:'puk1',APN:'apn'};Object.entries(data).forEach(([key,value])=>{const name=aliases[key]||key,field=form.elements[name];if(field&&value!==undefined&&value!==null)field.value=String(value)});if(data.k)$('#opc-k').value=data.k;if(data.op)$('#opc-op').value=data.op;if(data.opc)showOpc(data,true);$('#sim-confirm-imsi').value=data.imsi||'';$('#generated-profile-status').className='generated-profile-status ready';$('#generated-profile-status').textContent=`${source} profile loaded · PLMN ${data.plmn||'from worksheet'} · verify card read-back before provisioning.`;$('#sim-workflow-state').className='badge neutral';$('#sim-workflow-state').textContent='Profile prepared';setSimProcess('card','Profile ready')}
$('#generate-sim-profile').onclick=async()=>{if(!confirm('Generate a new IMSI and private authentication values for an owned programmable USIM? Unsaved profile values will be replaced.'))return;const button=$('#generate-sim-profile');button.disabled=true;button.textContent='Generating…';try{const data=await routingPost('api/sim/profile/generate',{confirm:'GENERATE'});fillSimProfile(data);toast('Complete private SIM profile generated')}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='Auto-generate'}};
$('#read-sim-card').onclick=async()=>{if(!confirm('Read non-secret identity and LTE network files from the inserted SIM? No card data will be changed.'))return;const button=$('#read-sim-card');button.disabled=true;button.textContent='Reading…';setIoLight('#sim-read-light','busy','Reading card');setSimProcess('card','Reading SIM');try{const data=await routingPost('api/sim/card/read',{confirm:'READ'});if(data.iccid)$('#sim-form').elements.iccid.value=data.iccid;if(data.imsi)$('#sim-form').elements.imsi.value=data.imsi;$('#sim-reader-result').innerHTML=`<div class="sim-read-result"><b>${escapeHtml(data.reader)}</b><span>ICCID ${escapeHtml(data.iccid||'not readable')} · IMSI ${escapeHtml(data.imsi||'not readable')}</span><small>ATR ${escapeHtml(data.atr)} · ${Object.keys(data.files).length} files read · ${Object.keys(data.errors).length} unavailable</small></div>`;setIoLight('#sim-read-light','online','Read complete');setSimProcess('worksheet','Card read');toast('SIM identity and network files read')}catch(e){setIoLight('#sim-read-light','offline','Read failed');setSimProcess('card','Read failed');$('#sim-reader-result').innerHTML=`<div class="connection-result error">${escapeHtml(e.message)}</div>`;toast(e.message)}finally{button.disabled=false;button.textContent='Read inserted SIM'}};
$('#import-sim-profile').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{const text=await file.text();let data;if(file.name.toLowerCase().endsWith('.json'))data=JSON.parse(text);else{data={};text.split(/\r?\n/).forEach(line=>{const match=line.match(/^([^:#][^:]*):\s*(.*)$/);if(match)data[match[1].trim()]=match[2].trim()})}fillSimProfile(data,'Imported');$('#sim-reader-result').innerHTML='<div class="connection-result success"><b>Private profile imported locally</b><span>The file stayed in this browser and was not uploaded to the app.</span></div>';toast('Private SIM profile imported')}catch(e){toast(`Import failed: ${e.message}`)}finally{event.target.value=''}};
