function simConfirmationMarkup(data){return `<div class="sim-confirm-grid">${data.checks.map(item=>`<div class="sim-confirm-check ${item.state}"><i></i><span><b>${escapeHtml(item.label)}</b><small>${escapeHtml(item.detail)}</small></span><em>${item.state==='online'?'Ready':item.state==='offline'?'Attention':'Not proven'}</em></div>`).join('')}</div>${data.evidence.length?`<details class="sim-evidence"><summary>Matching EPC evidence · ${data.evidence.length} lines</summary><pre>${escapeHtml(data.evidence.join('\n'))}</pre></details>`:''}`}
$('#confirm-sim-subscriber').onclick=async()=>{const imsi=$('#sim-confirm-imsi').value.trim(),button=$('#confirm-sim-subscriber');button.disabled=true;button.textContent='Checking…';setSimProcess('verify','Checking attach');try{const data=await routingPost('api/sim/confirm',{imsi});$('#sim-confirm-results').innerHTML=simConfirmationMarkup(data);$('#sim-confirm-state').className=`badge ${data.complete?'online':data.attach_confirmed?'neutral':'offline'}`;$('#sim-confirm-state').textContent=data.complete?'Production ready':data.attach_confirmed?'Attach found':'Needs attention';$('#sim-workflow-state').className=`badge ${data.complete?'online':'neutral'}`;$('#sim-workflow-state').textContent=data.complete?'Device online':'Confirmation incomplete';setSimProcess('verify',data.complete?'Production ready':data.attach_confirmed?'Attach found':'Needs attention');loadSimInventory();toast(data.complete?'Subscriber is online with proven data':'Review the remaining production checks')}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='Check production status'}};
async function loadLogs(){try{const params=new URLSearchParams({limit:'300'}),kind=$('#log-kind').value,search=$('#log-search').value.trim();if(kind)params.set('kind',kind);if(search)params.set('search',search);const rows=await jsonFetch(`api/logs?${params}`);$('#log-count').textContent=`${rows.length} entr${rows.length===1?'y':'ies'}`;$('#live-log').innerHTML=rows.length?rows.map(row=>`<div class="log-line"><time>${new Date(row.created_at*1000).toLocaleTimeString()}</time><span class="log-kind ${row.kind}">${escapeHtml(row.kind.toUpperCase())}</span><span>${escapeHtml(row.message)}</span></div>`).join(''):'<div class="log-line muted-line">No activity matches these filters.</div>';if($('#follow-logs').checked)$('#live-log').scrollTop=$('#live-log').scrollHeight}catch(e){toast(e.message)}}
$('#log-kind').onchange=loadLogs;
let logSearchTimer;
$('#log-search').oninput=()=>{clearTimeout(logSearchTimer);logSearchTimer=setTimeout(loadLogs,220)};
async function loadInternetPlan(){try{const data=await jsonFetch('api/internet-plan');$('#internet-plan').innerHTML=data.steps.map((step,index)=>`<div class="breakout-step"><b>${index+1}</b>${escapeHtml(step)}</div>`).join('')+`<div class="breakout-note">${escapeHtml(data.note)}</div>`}catch(e){$('#internet-plan').innerHTML=`<div class="warning">${escapeHtml(e.message)}</div>`}}
async function loadCommunications(){try{const data=await jsonFetch('api/communications/status'),badgeEl=$('#communications-badge');badgeEl.className=`badge ${data.ready?'online':data.enabled?'offline':'neutral'}`;badgeEl.textContent=data.ready?'Gateway ready':data.enabled?'Setup needed':'Disabled';$('#communications-readiness').className=`connection-result ${data.ready?'success':data.enabled?'error':''}`;$('#communications-readiness').innerHTML=`<b>${data.ready?'Outbound gateway is configured':data.enabled?'Communications need configuration':'Optional communications are disabled'}</b><span>${escapeHtml(data.native_volte_note)}</span>${data.sip.host?`<code>SIP ${escapeHtml(data.sip.transport.toUpperCase())} · ${escapeHtml(data.sip.host)}:${data.sip.port} · ${data.sip.online?'reachable':'unavailable'}</code>`:''}`;$$('#communications-form input, #communications-form select, #communications-form textarea, #communications-form button').forEach(control=>control.disabled=!data.ready)}catch(e){$('#communications-readiness').className='connection-result error';$('#communications-readiness').textContent=e.message}}
function renderToolOutput(data){const output=$('#network-tool-output');if(data.kind==='ports')output.innerHTML=data.rows.map(row=>`<div class="tool-result-row"><span><b>${escapeHtml(row.name)}</b><small>${escapeHtml(row.host)}:${row.port}</small></span><em class="${row.online?'pass':'fail'}">${row.online?`Open${row.latency_ms!==null?` · ${row.latency_ms} ms`:''}`:'Unavailable'}</em></div>`).join('');else if(data.kind==='routes')output.innerHTML=data.rows.map(row=>`<div class="tool-result-block ${row.ok?'pass':'fail'}"><b>${escapeHtml(row.name)} · ${escapeHtml(row.host)}</b><code>${escapeHtml(row.detail)}</code></div>`).join('');else if(data.kind==='uplink')output.innerHTML=`<div class="tool-result-row"><span><b>Public DNS</b><small>${escapeHtml((data.dns.addresses||[]).join(', ')||'No addresses')}</small></span><em class="${data.dns.online?'pass':'fail'}">${data.dns.online?'Ready':'Failed'}</em></div><div class="tool-result-row"><span><b>Public HTTPS</b><small>1.1.1.1:443 from the app</small></span><em class="${data.internet.online?'pass':'fail'}">${data.internet.online?'Ready':'Failed'}</em></div>`;else if(data.kind==='inventory')output.innerHTML=data.rows.length?data.rows.map(row=>`<div class="tool-result-row"><span><b>${escapeHtml(row.device_type)}</b><small>${row.critical||0} critical · ${row.unassigned||0} unassigned</small></span><em>${row.count} device${row.count===1?'':'s'}</em></div>`).join(''):'<div class="empty">No devices are registered yet.</div>';else output.innerHTML=data.rows.length?data.rows.map(item=>`<div class="incident ${item.state}"><i></i><span><b>${escapeHtml(item.label)} ${item.state}</b><small>${new Date(item.started_at*1000).toLocaleString()}${item.duration_seconds?` · ${formatDuration(item.duration_seconds)}`:''}</small></span></div>`).join(''):'<div class="empty">No incidents recorded in the last seven days.</div>'}
$$('[data-network-tool]').forEach(button=>button.onclick=async()=>{const output=$('#network-tool-output');output.innerHTML='<div class="empty">Running safe checks…</div>';$$('[data-network-tool]').forEach(control=>control.disabled=true);try{const data=await routingPost('api/tools/run',{action:button.dataset.networkTool});renderToolOutput(data);toast(`${data.title} complete`);loadLogs()}catch(e){output.innerHTML=`<div class="connection-result error">${escapeHtml(e.message)}</div>`;toast(e.message)}finally{$$('[data-network-tool]').forEach(control=>control.disabled=false)}});
$('#communications-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,body=Object.fromEntries(new FormData(form)),confirmation=prompt(`Send this ${body.kind} dispatch to ${body.to}? Type SEND to continue.`);if(!confirmation)return;body.confirm=confirmation;try{await routingPost('api/communications/send',body);form.reset();toast(`${body.kind==='voice'?'Voice announcement':'Text message'} accepted by the PBX gateway`);loadLogs()}catch(e){toast(e.message)}};
function routingPost(path,body={}){return jsonFetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}
async function loadRoutingAssistant(){
  try{
    const data=await jsonFetch('api/epc-routing/status'),cfg=data.config;
    $$('#routing-assistant button, #routing-assistant input').forEach(control=>control.disabled=!cfg.enabled);
    if(!cfg.enabled){$('#routing-access').className='routing-access';$('#routing-access').innerHTML='<b>Opt-in required.</b> In Home Assistant app Configuration, enable <code>epc_routing_management_enabled</code>, confirm the SSH user and uplink interface, then restart the app.';$('#routing-summary').textContent='Disabled in configuration';return}
    const secure=data.key_present&&data.host_trusted;
    $$('[data-console-action]').forEach(control=>control.disabled=!secure);
    $('#epc-console-state').textContent=secure?'Ready':'Access setup required';
    $('#routing-access').className=`routing-access ${secure?'ready':''}`;
    $('#routing-access').innerHTML=`<b>${escapeHtml(cfg.user)}@${escapeHtml(cfg.host)}:${cfg.port}</b> · SSH key ${data.key_present?'stored':'needed'} · host fingerprint ${data.host_trusted?'trusted':'not trusted'} · ${escapeHtml(cfg.subnet)} via ${escapeHtml(cfg.interface)}`;
    $('#routing-summary').textContent=secure?'Secure access ready':'Setup required';
    if(data.key_present){const keyData=await jsonFetch('api/epc-routing/key/generate');showEpcPublicKey(keyData.public_key)}
    const preview=await jsonFetch('api/epc-routing/preview');
    $('#routing-preview').innerHTML=preview.changes.map((change,index)=>`<div><b>${index+1}</b><span>${escapeHtml(change)}</span></div>`).join('')+`<small class="muted">${escapeHtml(preview.rollback)}</small>`;
  }catch(e){$('#routing-access').className='routing-access';$('#routing-access').textContent=e.message}
}
$('#routing-assistant').ontoggle=()=>{if($('#routing-assistant').open)loadRoutingAssistant()};
function setEpcKeyResult(message,state='') {const result=$('#epc-key-result');result.textContent=message;result.className=`key-result ${state}`.trim()}
$('#epc-key-form').onsubmit=async event=>{event.preventDefault();setEpcKeyResult('Checking and storing the private key…');try{const response=await fetch(api('api/epc-routing/key'),{method:'POST',body:new FormData(event.currentTarget)}),data=await response.json();if(!response.ok)throw new Error(data.error);setEpcKeyResult('Private key stored securely in Home Assistant.','success');toast('EPC SSH key stored privately');event.currentTarget.reset();loadRoutingAssistant()}catch(e){setEpcKeyResult(e.message,'error');toast(e.message)}};
function showEpcPublicKey(key){$('#epc-public-key').innerHTML=`<div class="public-key-box"><small>Install this public key in the EPC user’s authorized_keys file:</small><code>${escapeHtml(key)}</code><button class="secondary small" id="copy-epc-public-key">Copy public key</button></div>`;$('#copy-epc-public-key').onclick=async()=>{await navigator.clipboard.writeText(key);toast('EPC public key copied')}}
$('#generate-epc-key').onclick=async()=>{let confirmValue='';if($('#routing-access').textContent.includes('key stored')){confirmValue=prompt('A key already exists. Type REPLACE KEY to replace it. The old public key will stop working.');if(!confirmValue)return}setEpcKeyResult('Generating a dedicated key…');try{const data=await routingPost('api/epc-routing/key/generate',{confirm:confirmValue});showEpcPublicKey(data.public_key);setEpcKeyResult('Dedicated private key stored securely. Only the public key is shown above.','success');toast('Dedicated EPC key generated');loadRoutingAssistant()}catch(e){setEpcKeyResult(e.message,'error');toast(e.message)}};
$('#scan-epc-key').onclick=async()=>{try{const data=await routingPost('api/epc-routing/scan');$('#epc-fingerprints').innerHTML=`<div class="warning">Verify this fingerprint through a trusted source before accepting it.</div>`+data.fingerprints.map(item=>`<div class="fingerprint"><small>${escapeHtml(item.type)}</small><code>${escapeHtml(item.fingerprint)}</code><button class="secondary" data-trust-fingerprint="${escapeHtml(item.fingerprint)}">Trust this fingerprint</button></div>`).join('');$$('[data-trust-fingerprint]').forEach(button=>button.onclick=async()=>{try{await routingPost('api/epc-routing/trust',{fingerprint:button.dataset.trustFingerprint});toast('EPC host fingerprint trusted');$('#epc-fingerprints').innerHTML='';loadRoutingAssistant()}catch(e){toast(e.message)}})}catch(e){$('#epc-fingerprints').innerHTML=`<div class="connection-result error"><b>No fingerprint available</b><span>${escapeHtml(e.message)}</span></div>`;toast(e.message)}};
function renderEpcConnectivity(data){const state=data.ssh?'success':data.reachable?'warning':'error',banner=data.banner?`<code>${escapeHtml(data.banner)}</code>`:'';$('#epc-connectivity-result').className=`connection-result ${state}`;$('#epc-connectivity-result').innerHTML=`<b>${data.ssh?'SSH is reachable':'EPC access needs attention'}</b><span>${escapeHtml(data.detail)}</span>${banner}`;$('#epc-console-state').textContent=data.ssh?'SSH reachable':'Connection failed'}
$('#test-epc-access').onclick=async()=>{const button=$('#test-epc-access');button.disabled=true;button.textContent='Testing…';try{const data=await routingPost('api/epc-routing/connectivity');renderEpcConnectivity(data);toast(data.ssh?'EPC SSH is reachable':'EPC access needs attention')}catch(e){$('#epc-connectivity-result').className='connection-result error';$('#epc-connectivity-result').innerHTML=`<b>Connection test failed</b><span>${escapeHtml(e.message)}</span>`;toast(e.message)}finally{button.disabled=false;button.textContent='Test EPC access'}};
$$('[data-console-action]').forEach(button=>button.onclick=async()=>{const output=$('#epc-console-output');output.textContent=`Running ${button.textContent}…`;$$('[data-console-action]').forEach(control=>control.disabled=true);try{const data=await routingPost('api/epc-console/run',{action:button.dataset.consoleAction});output.textContent=`${data.label} · ${data.host}\n${new Date(data.checked_at*1000).toLocaleString()}\n\n${data.output}`;$('#epc-console-state').textContent='Connected';if(button.dataset.consoleAction==='logs'){await loadPendingRegistrations();toast(data.pending_registrations_found?`${data.pending_registrations_found} unknown subscriber registration found`:'Recent EPC logs scanned')}else toast(`${data.label} complete`)}catch(e){output.textContent=`Unable to open EPC console\n\n${e.message}`;$('#epc-console-state').textContent='Connection failed';toast(e.message)}finally{loadRoutingAssistant()}});
async function scanPendingFromEpc(){const buttons=[$('#scan-pending-registrations'),$('#scan-troubleshooting-registrations')];buttons.forEach(button=>{button.disabled=true;button.textContent='Scanning…'});try{const data=await routingPost('api/epc-console/run',{action:'logs'});await loadPendingRegistrations();toast(data.pending_registrations_found?`${data.pending_registrations_found} unknown subscriber registration found`:'No new unknown subscribers found')}catch(e){toast(e.message)}finally{buttons.forEach(button=>{button.disabled=false;button.textContent='Scan EPC logs'});$('#scan-troubleshooting-registrations').textContent='Scan recent EPC logs'}}
$('#scan-pending-registrations').onclick=scanPendingFromEpc;$('#scan-troubleshooting-registrations').onclick=scanPendingFromEpc;
function renderRoutingStatus(data){const names={forwarding:'IPv4 forwarding',interface:'Uplink interface',route:'EPC public route',nat:'NAT masquerade',outbound:'Subscriber outbound rule',return:'Established return rule',service:'Persistent routing service'};$('#routing-result').innerHTML=Object.entries(names).map(([key,name])=>`<div class="routing-check"><span>${name}</span><b class="${data.checks[key]?'pass':'fail'}">${data.checks[key]?'Ready':'Needs setup'}</b></div>`).join('')+`<div class="routing-check"><span>Observed packets</span><b>${data.counters.outbound} out · ${data.counters.return} back</b></div>`;$('#routing-summary').textContent=data.ready?'Routing ready':'Routing needs attention';$('#traffic-evidence').innerHTML=`<div><small>NAT PACKETS</small><b>${data.counters.nat.toLocaleString()}</b></div><div><small>OUTBOUND</small><b>${data.counters.outbound.toLocaleString()}</b></div><div><small>RETURN</small><b>${data.counters.return.toLocaleString()}</b></div><p>Counters refreshed ${new Date(data.checked_at*1000).toLocaleTimeString()}.</p>`}
$('#check-epc-routing').onclick=async()=>{try{const data=await routingPost('api/epc-routing/check');renderRoutingStatus(data);toast(data.ready?'EPC routing is ready':'Routing needs attention');refresh()}catch(e){toast(e.message)}};
$('#apply-epc-routing').onclick=async()=>{const host=window.LTE_CONFIG.epc_host,confirmation=prompt(`This changes forwarding and firewall rules on ${host}. Type APPLY ${host} to continue.`);if(!confirmation)return;try{const data=await routingPost('api/epc-routing/apply',{confirm:confirmation});renderRoutingStatus(data.status);toast('Subscriber Internet routing applied');refresh()}catch(e){toast(e.message)}};
$('#rollback-epc-routing').onclick=async()=>{const host=window.LTE_CONFIG.epc_host,confirmation=prompt(`Remove only Baiamonte-managed routing from ${host}. Type ROLLBACK ${host} to continue.`);if(!confirmation)return;try{await routingPost('api/epc-routing/rollback',{confirm:confirmation});toast('Baiamonte routing rolled back');$('#check-epc-routing').click()}catch(e){toast(e.message)}};
$('#start-ue-test').onclick=async()=>{try{const data=await routingPost('api/epc-routing/verify/start');$('#routing-result').innerHTML=`<div class="traffic-result pass"><b>Test recording started.</b><br>${escapeHtml(data.instruction)}</div>`;$('#finish-ue-test').hidden=false;$('#start-ue-test').hidden=true}catch(e){toast(e.message)}};
$('#finish-ue-test').onclick=async()=>{try{const data=await routingPost('api/epc-routing/verify/finish');$('#routing-result').innerHTML=`<div class="traffic-result ${data.verified?'pass':'fail'}"><b>${data.verified?'UE Internet path verified':'Traffic test needs attention'}</b><br>${escapeHtml(data.message)}<br><small>New packets: ${data.delta.outbound} out · ${data.delta.return} back</small></div>`;$('#finish-ue-test').hidden=true;$('#start-ue-test').hidden=false;$('#routing-summary').textContent=data.verified?'UE Internet verified':'Verification needed';refresh()}catch(e){toast(e.message)}};
$('#run-diagnostics').onclick=async()=>{const button=$('#run-diagnostics');button.disabled=true;button.textContent='Running…';try{const data=await jsonFetch('api/diagnostics/run',{method:'POST'}),ok=!data.failures;badge($('#diagnostic-summary'),ok);$('#diagnostic-summary').textContent=ok?'All checks passed':`${data.failures} need attention`;$('#diagnostic-results').innerHTML=data.checks.map(check=>`<div class="check ${check.ok?'pass':'fail'}"><span>${check.ok?'✓':'!'}</span><div><b>${escapeHtml(check.name)}</b><small>${escapeHtml(check.detail)}</small>${!check.ok&&check.suggestion?`<em>${escapeHtml(check.suggestion)}</em>`:''}</div></div>`).join('');renderVisibility(data.visibility);loadLogs()}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='Run diagnostics'}};
$('#log-analyze-form').onsubmit=async event=>{event.preventDefault();try{const response=await fetch(api('api/logs/analyze'),{method:'POST',body:new FormData(event.target)}),data=await response.json();if(!response.ok)throw new Error(data.error);const captured=data.pending_registrations_found?`<div class="warning success"><b>${data.pending_registrations_found} unknown subscriber registration captured.</b><br>Review it below or in Estate devices before provisioning.</div>`:'';$('#log-findings').innerHTML=captured+(data.findings.length?`<p class="muted">${data.lines} lines analyzed</p>`+data.findings.map(f=>`<div class="finding"><b>${escapeHtml(f.title)} · ${f.count}</b><span>${escapeHtml(f.action)}</span></div>`).join(''):`<div class="warning success">No known error patterns found in ${data.lines} lines.</div>`);await loadPendingRegistrations();loadLogs()}catch(e){toast(e.message)}};
$('#clear-log-view').onclick=()=>{$('#live-log').innerHTML='<div class="log-line muted-line">View cleared. New activity will appear here.</div>'};
setInterval(()=>{if($('#diagnostics').classList.contains('active')&&$('#follow-logs').checked)loadLogs()},4000);
setInterval(()=>{if($('#bts').classList.contains('active'))loadBtsStatus()},30000);
window.addEventListener('hashchange',()=>showPage(location.hash.slice(1)||'overview',false));
showPage(location.hash.slice(1)||'overview',false);refresh();
